        .user-bubble { background: var(--primary); color: #fff; padding: 12px 18px; border-radius: var(--radius-lg) var(--radius-lg) var(--radius-sm) var(--radius-lg); font-size: 0.95rem; line-height: 1.5; }
        .ai-content { background: var(--surface); padding: 12px 18px; border-radius: var(--radius-lg) var(--radius-lg) var(--radius-lg) var(--radius-sm); font-size: 0.95rem; line-height: 1.6; }
        .ai-content p { margin-bottom: 1em; }
        .ai-content pre { background: #000; border: 1px solid var(--border); border-radius: var(--radius-md); padding: 16px; margin: 16px 0; font-size: 0.85rem; overflow-x: auto; }

        .input-area { padding: 16px 24px; background: rgba(0,0,0,0.8); backdrop-filter: blur(20px); border-top: 1px solid var(--border); z-index: 50; flex-shrink: 0; }
        @supports (padding: max(0px)) { 
            .input-area { padding-bottom: max(16px, env(safe-area-inset-bottom)); } 
            .header { padding-top: max(0px, env(safe-area-inset-top)); }
        }
        .input-wrapper { display: flex; gap: 12px; align-items: flex-end; max-width: 800px; margin: 0 auto; }
        .message-input { flex: 1; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-lg); padding: 14px 18px; color: var(--text); font-size: 1rem; resize: none; outline: none; transition: all 0.2s; min-height: 52px; max-height: 200px; line-height: 1.4; }
        .message-input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--border-glow); }
        .send-btn { width: 52px; height: 52px; border-radius: 50%; cursor: pointer; display: flex; align-items: center; justify-content: center; border: none; background: var(--primary); color: #fff; transition: all 0.2s; font-size: 1rem; flex-shrink: 0; }
        .send-btn:hover:not(:disabled) { filter: brightness(1.2); }
        .send-btn:disabled { background: var(--surface); color: var(--text-muted); cursor: not-allowed; }

        /* --- Service Interface Layout --- */
        .service-interface { padding: 24px; max-width: 1000px; margin: 0 auto; animation: fadeIn 0.5s ease; overflow-y: auto; height: 100%; }
        .interface-header { text-align: center; margin-bottom: 32px; }
        .interface-header h2 { font-size: 1.8rem; font-weight: 700; display: flex; align-items: center; gap: 12px; justify-content: center; }
        .interface-header p { font-size: 0.9rem; color: var(--text-muted); max-width: 500px; margin: 8px auto 0; }
        .interface-content { display: flex; flex-direction: column; gap: 24px; }
        .input-section { display: flex; flex-direction: column; gap: 16px; }
        .input-section h3 { font-size: 1.2rem; font-weight: 600; padding-bottom: 8px; border-bottom: 1px solid var(--border); }
        textarea, input, select { width: 100%; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 14px; font-size: 1rem; color: var(--text); outline: none; transition: all 0.2s; }
        textarea:focus, input:focus, select:focus { border-color: var(--primary); box-shadow: 0 0 0 3px var(--border-glow); }
        .action-buttons { margin-top: 16px; display: flex; justify-content: center; }
        .primary-btn, .secondary-btn { padding: 12px 24px; font-weight: 600; border-radius: var(--radius-md); border: 1px solid transparent; cursor: pointer; transition: all 0.2s; display: inline-flex; align-items: center; gap: 8px; }
        .primary-btn { background: var(--primary); color: white; }
        .primary-btn:hover { filter: brightness(1.15); }
        .secondary-btn { background: var(--surface); color: var(--text); border-color: var(--border); }
        .secondary-btn:hover { background: var(--glass-strong); }

        /* Grid Layouts for Forms & Results */
        .options-grid, .input-grid, .stats-grid { display: grid; gap: 16px; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
        .input-group, .option-group { display: flex; flex-direction: column; gap: 8px; }
        .input-group label, .option-group label { font-size: 0.9rem; font-weight: 500; color: var(--text-muted); }
        .stat-item { background: var(--glass); border: 1px solid var(--border); border-radius: var(--radius-md); padding: 16px; text-align: center; display: flex; flex-direction: column; gap: 4px; }
        .stat-number { font-size: 1.8rem; font-weight: 700; color: var(--text); }
        .stat-label { font-size: 0.8rem; color: var(--text-muted); }

        .tab-selector { display: flex; background: var(--surface); padding: 4px; border-radius: var(--radius-md); align-self: center; margin-bottom: 16px; }
        .tab-btn { padding: 8px 16px; font-weight: 500; background: none; border: none; color: var(--text-muted); cursor: pointer; border-radius: var(--radius-sm); transition: all 0.2s; }
        .tab-btn.active { background: var(--glass-strong); color: var(--text); }
        .tab-content { display: none; } .tab-content.active { display: block; }

        .switch-container { display: flex; justify-content: space-between; align-items: center; background: var(--glass); padding: 12px; border-radius: var(--radius-md); }
        .switch { position: relative; display: inline-block; width: 44px; height: 24px; }
        .switch input { opacity: 0; width: 0; height: 0; }
        .slider { position: absolute; cursor: pointer; top: 0; left: 0; right: 0; bottom: 0; background-color: var(--border); border-radius: 34px; transition: .4s; }
        .slider:before { position: absolute; content: ""; height: 18px; width: 18px; left: 3px; bottom: 3px; background-color: white; border-radius: 50%; transition: .4s; }
        input:checked + .slider { background-color: var(--primary); }
        input:checked + .slider:before { transform: translateX(20px); }

        .result-card { margin-top: 24px; }

        @media (min-width: 769px) {
            .sidebar.open ~ .main-content { margin-left: var(--sidebar-width); }
        }
        @media (max-width: 768px) {
            .sidebar { width: 100vw; transform: translateX(-100vw); }
            .sidebar-overlay.active { opacity: 1; visibility: visible; }
            .header { padding: 0 16px; height: 56px; }
            .messages-container, .service-interface, .input-area { padding: 16px; }
            .welcome-title { font-size: 1.8rem; }
            .user-bubble, .ai-content { font-size: 0.95rem; padding: 10px 16px; }
            .input-wrapper { gap: 8px; }
            .message-input { min-height: 48px; padding: 12px 16px; }
            .send-btn { width: 48px; height: 48px; }
        }
    </style>
</head>

<body>
    <div class="aurora-background">
        <div class="aurora one"></div>
        <div class="aurora two"></div>
    </div>
    <div class="sidebar-overlay" id="sidebarOverlay"></div>

    <div class="container">
        <aside class="sidebar" id="sidebar" role="navigation">
            <header class="sidebar-header">
                <div class="logo">
                    <div class="logo-icon" id="logo-icon-container"></div>
                    <div class="logo-text">
                        <h1>JADED</h1>
                        <p>Deep Discovery AI</p>
                    </div>
                </div>
                <button class="new-chat-btn" onclick="newChat()">
                    <span>Új Beszélgetés</span>
                    <i class="fas fa-plus"></i>
                </button>
            </header>
            <div class="sidebar-content" id="sidebarContent"></div>
            <footer class="sidebar-footer">
                <p>JADED v4.2 by Sándor Kollár</p>
            </footer>
        </aside>

        <main class="main-content" id="mainContent">
            <header class="header">
                <button class="menu-toggle" onclick="toggleSidebar()" aria-label="Menü">
                    <i class="fas fa-bars"></i>
                </button>
                <h1 class="header-title" id="main-header-title">JADED</h1>
                <div style="width: 40px;"></div> <!-- Spacer -->
            </header>

            <div class="chat-area">
                <section class="messages-container" id="messagesContainer" aria-live="polite">
                    <div class="welcome-screen" id="welcomeScreen">
                        <h1 class="welcome-title">JADED AI</h1>
                        <p class="welcome-subtitle">
                            Fejlett tudományos kutatási platform a legmodernebb számítási modellekkel. Válasszon egy szolgáltatást, vagy írjon üzenetet a kezdéshez.
                        </p>
                    </div>
                </section>

                <footer class="input-area">
                    <div class="input-wrapper">
                        <textarea class="message-input" id="messageInput" placeholder="Kérdezzen bármit..." rows="1" aria-label="Üzenet"></textarea>
                        <button class="send-btn" id="sendBtn" onclick="sendMessage()" aria-label="Küldés" disabled>
                            <i class="fas fa-arrow-up"></i>
                        </button>
                    </div>
                </footer>
            </div>
        </main>
    </div>

    <script>
        // --- Global State & Config ---
        const AppState = { isTyping: false };
        const FAKE_API_DELAY = 100;

        // --- DOM Elements ---
        const getEl = id => document.getElementById(id);
        const sidebar = getEl('sidebar'), sidebarOverlay = getEl('sidebarOverlay'), sidebarContent = getEl('sidebarContent'),
              mainContent = getEl('mainContent'), messagesContainer = getEl('messagesContainer'), 
              messageInput = getEl('messageInput'), sendBtn = getEl('sendBtn'), mainHeaderTitle = getEl('main-header-title');
        let welcomeScreen = getEl('welcomeScreen');

        // --- Theme Manager ---
        class DynamicThemeManager {
            constructor() { this.auroraBlobs = document.querySelectorAll('.aurora-background .aurora'); setTimeout(() => this.auroraBlobs.forEach(b => b.classList.add('visible')), 500); }
        }

        // --- FAKE API ---
        async function fakeApiCall(endpoint, options) {
            console.log(`[FAKE API] Calling ${endpoint} with options:`, options);
            if (Math.random() < 0.05) {
                 await new Promise(res => setTimeout(res, 500));
                 throw new Error("Szimulált hálózati hiba. Kérlek próbáld újra.");
            }
            await new Promise(res => setTimeout(res, FAKE_API_DELAY));

            const body = (options && options.body) ? options.body : {};

            if (endpoint.includes('alphafold')) {
                return { 
                    data: {
                        plddt: 92.5 + Math.random() * 5, ptm: 0.85 + Math.random() * 0.1, iptm: 0.80 + Math.random() * 0.1,
                        ranking_score: 0.82 + Math.random() * 0.1, has_clashes: Math.random() < 0.1,
                        pdb_content: `REMARK FAKE PDB FOR SEQUENCE: ${body.sequence}`
                    },
                    quantum_data: body.quantum_enhancement ? {
                        coherence_factor: 0.85 + Math.random() * 0.1, entanglement_map_max: 0.9 + Math.random() * 0.05,
                        job_id: `q_job_${Math.random().toString(36).substr(2, 9)}`
                    } : null
                };
            }
            if (endpoint.includes('drug_affinity')) {
                return { data: { total_affinity: -9.5 + Math.random() * 2, ic50_nM: 50 + Math.random() * 100, interaction_breakdown: { 'Elektrosztatikus': -3.0 + Math.random(), 'van der Waals': -4.5 + Math.random(), 'Hidrogénhíd': -2.0 + Math.random() } } };
            }
            if (endpoint.includes('ppi')) {
                 return { data: { binding_affinity: -12.0 + Math.random() * 3, quantum_coherence: 0.78 + Math.random() * 0.1, hotspots: 5 + Math.floor(Math.random() * 5) } };
            }
            return { response: "A szimulált backend sikeresen válaszolt." };
        }

        // --- UI Functions ---
        const createSVGLogo = () => getEl('logo-icon-container').innerHTML = `<svg viewBox="0 0 100 100" xmlns=""><path d="M 30 28 C 30 50 50 72 70 72" stroke="white" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="30" cy="72" r="6" fill="white"/></svg>`;
        function toggleSidebar() {
            const isOpen = sidebar.classList.toggle('open');
            if (window.innerWidth <= 768) {
                sidebarOverlay.classList.toggle('active', isOpen);
            }
        }
        function closeSidebar() { 
            if (sidebar.classList.contains('open')) {
                toggleSidebar();
            }
        }
        const hideWelcome = () => { if (welcomeScreen) { welcomeScreen.style.display = 'none'; welcomeScreen = null; } };
        function newChat() {
            messagesContainer.innerHTML = '';
            mainHeaderTitle.textContent = "JADED";
            const newWelcomeScreen = document.createElement('div');
            newWelcomeScreen.className = 'welcome-screen'; newWelcomeScreen.id = 'welcomeScreen';
            newWelcomeScreen.innerHTML = `<h1 class="welcome-title">JADED AI</h1><p class="welcome-subtitle">Készen állok a következő feladatra. Válassz egy szolgáltatást, vagy kérdezz bármit!</p>`;
            messagesContainer.appendChild(newWelcomeScreen);
            welcomeScreen = getEl('welcomeScreen');
            messageInput.value = ''; messageInput.dispatchEvent(new Event('input')); messageInput.focus();
            document.querySelectorAll('.service-item.active').forEach(item => item.classList.remove('active'));
            closeSidebar();
        }

        // --- Service Loading & Display ---
        function loadServices() {
            const services = {
                biologiai_orvosi: { name: 'Biológiai & Orvosi', icon: 'fa-dna', items: { 'AlphaFold 3++': '', 'Quantum Drug Affinity': '', 'Protein-Protein Interaction': '', 'AlphaGenome': '' } },
                kemiai_anyagtudomanyi: { name: 'Kémiai & Anyagtudományi', icon: 'fa-atom', items: { 'Quantum Chemistry': '', 'Molecular Dynamics': '', '3D Conformer Generation': '' } },
                technologiai_melymu: { name: 'Technológiai & Mélyműszaki', icon: 'fa-microchip', items: { 'Neural Networks': '', 'Robotics Simulation': '', 'Spintronics Simulation': '' } },
            };
            sidebarContent.innerHTML = '';
            for (const categoryId in services) {
                const category = services[categoryId];
                let servicesHTML = Object.keys(category.items).map(name => `<div class="service-item" onclick="selectService(this, '${escapeHtml(name).replace(/'/g, `\\'`)}')"><div class="service-icon"><i class="fas ${category.icon}"></i></div><div class="service-info"><h4>${escapeHtml(name)}</h4></div></div>`).join('');
                const categoryDiv = document.createElement('div');
                categoryDiv.className = 'service-category';
                categoryDiv.innerHTML = `<div class="category-header" onclick="toggleCategory(this)"><div class="category-title"><span>${category.name}</span></div><i class="fas fa-chevron-down"></i></div><div class="category-services"><div>${servicesHTML}</div></div>`;
                sidebarContent.appendChild(categoryDiv);
            }
        }
        const toggleCategory = header => { const s = header.nextElementSibling; const c = header.querySelector('.fa-chevron-down'); s.classList.toggle('open'); c.style.transform = s.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)'; };
        function selectService(element, serviceName) { 
            document.querySelectorAll('.service-item.active').forEach(item => item.classList.remove('active'));
            element.classList.add('active');
            hideWelcome(); 
            mainHeaderTitle.textContent = serviceName; 
            showServiceInterface(serviceName); 
            closeSidebar(); 
        }

        // --- Messaging ---
        async function sendMessage() { const message = messageInput.value.trim(); if (!message || AppState.isTyping) return; hideWelcome(); addUserMessage(message); messageInput.value = ''; sendBtn.disabled = true; messageInput.style.height = 'auto'; showTypingIndicator(); try { const data = await fakeApiCall('/chat', { body: { message } }); addAiMessage(data.response); } catch(e) { addAiMessage(`**Hiba:** ${e.message}`); } finally { hideTypingIndicator(); } }
        const addUserMessage = content => { const div = document.createElement('div'); div.className = 'message user-message'; div.innerHTML = `<div class="user-bubble">${escapeHtml(content)}</div>`; messagesContainer.appendChild(div); scrollToBottom(); };
        function addAiMessage(content) { const div = document.createElement('div'); div.className = 'message ai-message'; div.innerHTML = `<div class="ai-content">${marked.parse(content)}</div>`; messagesContainer.appendChild(div); if (typeof hljs !== 'undefined') hljs.highlightAll(); scrollToBottom(); }
        function showTypingIndicator() { if(AppState.isTyping) return; AppState.isTyping = true; const i = document.createElement('div'); i.id = 'typingIndicator'; i.className = 'message ai-message'; i.innerHTML = `<div style="background: var(--surface); padding: 10px 16px; border-radius: var(--radius-lg);"><div style="display:flex; gap:4px;"><div style="animation: typingPulse 1.4s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.16s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.32s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div></div></div><style>@keyframes typingPulse { 0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; } 40% { transform: scale(1.2); opacity: 1; } }</style>`; messagesContainer.appendChild(i); scrollToBottom(); }
        const hideTypingIndicator = () => { AppState.isTyping = false; const i = getEl('typingIndicator'); if (i) i.remove(); };

        // --- Utilities & Event Listeners ---
        const escapeHtml = text => { const d = document.createElement('div'); d.textContent = String(text); return d.innerHTML; };
        const scrollToBottom = () => messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });
        function setupEventListeners() {
            messageInput.addEventListener('input', () => { const hasText = messageInput.value.trim().length > 0; sendBtn.disabled = !hasText; messageInput.style.height = 'auto'; messageInput.style.height = `${Math.min(messageInput.scrollHeight, 200)}px`; });
            messageInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } });
            sidebarOverlay.addEventListener('click', closeSidebar);
        }

        // --- Service Interfaces ---
        function showServiceInterface(serviceName) {
            let interfaceHTML = '';
            switch (serviceName) {
                case 'AlphaFold 3++': interfaceHTML = getAlphaFoldInterface(); break;
                case 'Quantum Drug Affinity': interfaceHTML = getDrugAffinityInterface(); break;
                case 'Protein-Protein Interaction': interfaceHTML = getPPIInterface(); break;
                default: interfaceHTML = getGenericInterface(serviceName, 'Adja meg a bemeneti adatokat a számításhoz.'); break;
            }
            messagesContainer.innerHTML = interfaceHTML;
            if (serviceName === 'AlphaFold 3++') getEl('proteinSequence')?.addEventListener('input', updateSequenceStats);
        }

        const getAlphaFoldInterface = () => `<div class="service-interface"><header class="interface-header"><h2><i class="fas fa-dna accent"></i> AlphaFold 3++</h2><p>Fehérje folding, komplex és ligand interakció előrejelzés kvantum finomítással.</p></header><div class="interface-content"><div class="tab-selector"><button class="tab-btn active" onclick="switchTab(this, 's-tab')">Szekvencia</button><button class="tab-btn" onclick="switchTab(this, 'c-tab')">Komplex</button><button class="tab-btn" onclick="switchTab(this, 'l-tab')">Ligand</button></div><div id="s-tab" class="tab-content active"><section class="input-section"><h3>Protein Szekvencia</h3><textarea id="proteinSequence" placeholder="Írja be a protein szekvenciát..." rows="6"></textarea><div class="sequence-stats"><span id="sequence-length">Hossz: 0</span></div></section></div><div id="c-tab" class="tab-content"><section class="input-section"><h3>Multi-Chain Komplex</h3><div id="chain-builder" class="input-grid" style="grid-template-columns: 1fr;"><div class="input-group"><label>Lánc A:</label><textarea placeholder="Első protein..." rows="3"></textarea></div><div class="input-group"><label>Lánc B:</label><textarea placeholder="Második protein..." rows="3"></textarea></div></div><button class="secondary-btn" onclick="addChain()">+ Új Lánc</button></section></div><div id="l-tab" class="tab-content"><section class="input-section"><h3>Protein-Ligand</h3><div class="input-group"><label>Ligand (SMILES)</label><input type="text" id="ligand-smiles" placeholder="pl.: CC(=O)OC1=CC=CC=C1C(=O)O"></div></section></div><section class="input-section"><h3>Beállítások</h3><div class="options-grid"><div class="option-group"><label>Recycle</label><input type="number" id="recycle-iterations" value="3" min="1" max="20"></div><div class="switch-container"><label for="quantum-enhancement">Kvantum Finomítás</label><label class="switch"><input type="checkbox" id="quantum-enhancement"><span class="slider"></span></label></div></div></section><div class="action-buttons"><button class="primary-btn" onclick="runAlphaFoldPrediction()"><i class="fas fa-rocket"></i> Predikció</button></div><div id="service-results"></div></div></div>`;
        const getDrugAffinityInterface = () => `<div class="service-interface"><header class="interface-header"><h2>Kvantum Gyógyszer Affinitás</h2><p>Számítsa ki egy ligand kötődési affinitását kvantum-korrekciókkal.</p></header><div class="interface-content"><div class="input-grid"><section class="input-section"><h3>Protein Célpont</h3><textarea id="protein-target" placeholder="Protein szekvencia vagy UniProt ID" rows="4"></textarea></section><section class="input-section"><h3>Ligand</h3><input type="text" id="ligand-smiles" placeholder="SMILES kód"></section></div><div class="action-buttons"><button class="primary-btn" onclick="runDrugAffinity()"><i class="fas fa-calculator"></i> Számítás</button></div><div id="service-results"></div></div></div>`;
        const getPPIInterface = () => `<div class="service-interface"><header class="interface-header"><h2>Protein-Protein Interakció</h2><p>Jelezze előre két protein kölcsönhatását.</p></header><div class="interface-content"><div class="input-grid"><section class="input-section"><h3>Protein A</h3><textarea id="proteinA_seq" placeholder="Első szekvencia..." rows="5"></textarea></section><section class="input-section"><h3>Protein B</h3><textarea id="proteinB_seq" placeholder="Második szekvencia..." rows="5"></textarea></section></div><div class="action-buttons"><button class="primary-btn" onclick="runPPI()"><i class="fas fa-search-plus"></i> Elemzés</button></div><div id="service-results"></div></div></div>`;
        const getGenericInterface = (name, desc) => `<div class="service-interface"><header class="interface-header"><h2>${name}</h2><p>${desc}</p></header><div class="interface-content"><section class="input-section"><textarea id="serviceInput" placeholder="Bemeneti adatok..." rows="8"></textarea></section><div class="action-buttons"><button class="primary-btn" onclick="runGenericService('${name}')"><i class="fas fa-play"></i> Indítás</button></div><div id="service-results"></div></div></div>`;

        // --- Service Logic ---
        const switchTab = (btn, tabId) => { btn.parentElement.querySelector('.active').classList.remove('active'); btn.classList.add('active'); btn.closest('.interface-content').querySelector('.tab-content.active').classList.remove('active'); getEl(tabId).classList.add('active'); };
        const updateSequenceStats = () => getEl('sequence-length').textContent = `Hossz: ${getEl('proteinSequence').value.replace(/[^A-Za-z]/g, '').length}`;
        function addChain() { const b = getEl('chain-builder'); const c = b.children.length; const l = String.fromCharCode(65 + c); const i = document.createElement('div'); i.className = 'input-group'; i.innerHTML = `<label>Lánc ${l}:</label><textarea placeholder="Szekvencia..." rows="3"></textarea>`; b.appendChild(i); }

        async function runAlphaFoldPrediction() {
            const sequence = getEl('proteinSequence').value; if (!sequence) return;
            const quantum_enhancement = getEl('quantum-enhancement').checked;
            let steps = [{ text: "MSA generálása...", duration: 1500 }, { text: "Evoformer futtatása...", duration: 3000 }, { text: "Szerkezeti modul...", duration: 1000 }, { text: "Diffúziós modell...", duration: 2500 }, { text: "Konfidencia számítása...", duration: 800 }];
            if(quantum_enhancement) steps.splice(1, 0, { text: "Csatlakozás kvantum backendhez...", duration: 1200 }, { text: "Kvantum áramkör futtatása...", duration: 2000 });
            await showProgressAndRun('AlphaFold 3 Predikció', steps, async () => {
                const { data, quantum_data } = await fakeApiCall('/alphafold', { body: { sequence, quantum_enhancement } });
                let qInfo = quantum_data ? `<h4>Kvantum Finomítás</h4><div class="stats-grid"><div class="stat-item"><span class="stat-number">${quantum_data.coherence_factor.toFixed(3)}</span><span class="stat-label">Koherencia</span></div><div class="stat-item"><span class="stat-number">${quantum_data.entanglement_map_max.toFixed(3)}</span><span class="stat-label">Összefonódás</span></div><div class="stat-item"><span class="stat-number" style="font-size: 0.9rem; word-break: break-all;">${quantum_data.job_id}</span><span class="stat-label">Job ID</span></div></div>` : '';
