<script>
const AppState = { isTyping: false };
const API_BASE = '';
const getEl = id => document.getElementById(id);
const sidebar = getEl('sidebar'), sidebarOverlay = getEl('sidebarOverlay'), sidebarContent = getEl('sidebarContent'), mainContent = getEl('mainContent'), messagesContainer = getEl('messagesContainer'), messageInput = getEl('messageInput'), sendBtn = getEl('sendBtn'), mainHeaderTitle = getEl('main-header-title');
let welcomeScreen = getEl('welcomeScreen');
class DynamicThemeManager {
constructor() { this.auroraBlobs = document.querySelectorAll('.aurora-background .aurora'); setTimeout(() => this.auroraBlobs.forEach(b => b.classList.add('visible')), 500); }
}
new DynamicThemeManager();
async function apiCall(endpoint, options = {}) {
try {
const response = await fetch(`${API_BASE}${endpoint}`, {
...options,
headers: { 'Content-Type': 'application/json', ...(options.headers || {}) }
});
if (!response.ok) throw new Error(`HTTP ${response.status}: ${response.statusText}`);
return await response.json();
} catch (error) {
console.error(`API call failed: ${endpoint}`, error);
throw error;
}
}
const createSVGLogo = () => getEl('logo-icon-container').innerHTML = `<svg viewBox="0 0 100 100" xmlns=""><path d="M 30 28 C 30 50 50 72 70 72" stroke="white" stroke-width="8" fill="none" stroke-linecap="round"/><circle cx="30" cy="72" r="6" fill="white"/></svg>`;
function toggleSidebar() {
const isOpen = sidebar.classList.toggle('open');
if (window.innerWidth <= 768) { sidebarOverlay.classList.toggle('active', isOpen); }
}
function closeSidebar() { if (sidebar.classList.contains('open')) { toggleSidebar(); } }
const hideWelcome = () => { if (welcomeScreen) { welcomeScreen.style.display = 'none'; welcomeScreen = null; } };
function newChat() {
messagesContainer.innerHTML = '';
mainHeaderTitle.textContent = "JADED";
const newWelcomeScreen = document.createElement('div');
newWelcomeScreen.className = 'welcome-screen'; newWelcomeScreen.id = 'welcomeScreen';
newWelcomeScreen.innerHTML = `<h1 class="welcome-title">JADED AI</h1><p class="welcome-subtitle">Készen állok a következő feladatra. Válassz egy szolgáltatást, vagy kérdezz bármit!</p>`;
messagesContainer.appendChild(newWelcomeScreen);
welcomeScreen = getEl('welcomeScreen');
messageInput.value = ''; messageInput.dispatchEvent(new Event('input')); messageInput.focus();
document.querySelectorAll('.service-item.active').forEach(item => item.classList.remove('active'));
closeSidebar();
}
function loadServices() {
const services = {
biologiai_orvosi: {
name: 'Biológiai & Orvosi',
icon: 'fa-dna',
items: {
'AlphaFold 3++': 'Fehérje szerkezet predikció kvantum finomítással',
'Quantum Drug Affinity': 'Gyógyszer-kötődési affinitás kvantum számítással',
'Protein-Protein Interaction': 'Fehérje-fehérje kölcsönhatás előrejelzés',
'AlphaGenome': 'Genomikus variáns hatás előrejelzés',
'AlphaFold Proteome': 'Teljes proteóm letöltés és elemzés',
'Quantum Docking': 'Molekuláris dokkolás kvantum módszerrel',
'Spectral Validation': 'IR/NMR spektrális validáció'
}
},
kemiai_anyagtudomanyi: {
name: 'Kémiai & Anyagtudományi',
icon: 'fa-atom',
items: {
'Quantum Chemistry': 'Kvantumkémiai számítások (PySCF)',
'Molecular Dynamics': 'Molekuláris dinamika szimuláció',
'3D Conformer Generation': 'Konformer generálás (AQME, CDPKit)',
'Molecule Design': 'Generatív AI molekula tervezés',
'Chemical Clustering': 'Molekula klaszterezés és elemzés',
'Property Prediction': 'Kémiai tulajdonságok előrejelzése'
}
},
technologiai_melymu: {
name: 'Technológiai & Mélyműszaki',
icon: 'fa-microchip',
items: {
'Neural Networks': 'Neurális hálók tanítása és inferencia',
'Robotics Simulation': 'Robotika szimuláció és tervezés',
'Spintronics Simulation': 'Spintronikai eszközök szimulációja',
'Pipeline Optimization': 'Aszinkron feldolgozási pipeline',
'Hardware Acceleration': 'GPU/CUDA gyorsítás',
'Compression Codec': 'Differenciálható tömörítési kodek'
}
},
quantum_computing: {
name: 'Kvantumszámítás',
icon: 'fa-atom',
items: {
'IQM Quantum Circuits': 'IQM kvantumszámítógépek használata',
'IBM Quantum': 'IBM Quantum Network hozzáférés',
'Quantum Circuit Design': 'Kvantum áramkör tervezés',
'Protein Quantum Analysis': 'Fehérjék kvantum-mechanikai elemzése'
}
},
adatelemzes: {
name: 'Adatelemzés',
icon: 'fa-chart-line',
items: {
'Data Analysis': 'Általános adatelemzés',
'Visualization': 'Adatvizualizáció',
'Statistical Modeling': 'Statisztikai modellezés',
'Machine Learning': 'Gépi tanulási modellek'
}
}
};
sidebarContent.innerHTML = '';
for (const categoryId in services) {
const category = services[categoryId];
let servicesHTML = Object.entries(category.items).map(([name, desc]) =>
`<div class="service-item" onclick="selectService(this, '${escapeHtml(name).replace(/'/g, `\\'`)}')">
<div class="service-icon"><i class="fas ${category.icon}"></i></div>
<div class="service-info">
<h4>${escapeHtml(name)}</h4>
${desc ? `<p>${escapeHtml(desc)}</p>` : ''}
</div>
</div>`
).join('');
const categoryDiv = document.createElement('div');
categoryDiv.className = 'service-category';
categoryDiv.innerHTML = `
<div class="category-header" onclick="toggleCategory(this)">
<div class="category-title"><span>${category.name}</span></div>
<i class="fas fa-chevron-down"></i>
</div>
<div class="category-services open"><div>${servicesHTML}</div></div>
`;
sidebarContent.appendChild(categoryDiv);
}
}
const toggleCategory = header => {
const s = header.nextElementSibling;
const c = header.querySelector('.fa-chevron-down');
s.classList.toggle('open');
c.style.transform = s.classList.contains('open') ? 'rotate(180deg)' : 'rotate(0deg)';
};
function selectService(element, serviceName) {
document.querySelectorAll('.service-item.active').forEach(item => item.classList.remove('active'));
element.classList.add('active');
hideWelcome();
mainHeaderTitle.textContent = serviceName;
showServiceInterface(serviceName);
closeSidebar();
}
async function sendMessage() {
const message = messageInput.value.trim();
if (!message || AppState.isTyping) return;
hideWelcome();
addUserMessage(message);
messageInput.value = '';
sendBtn.disabled = true;
messageInput.style.height = 'auto';
showTypingIndicator();
try {
const data = await apiCall('/chat', {
method: 'POST',
body: JSON.stringify({ message })
});
addAiMessage(data.response || 'Sikeresen feldolgozva.');
} catch(e) {
addAiMessage(`**Hiba:** ${e.message}`);
} finally {
hideTypingIndicator();
}
}
const addUserMessage = content => {
const div = document.createElement('div');
div.className = 'message user-message';
div.innerHTML = `<div class="user-bubble">${escapeHtml(content)}</div>`;
messagesContainer.appendChild(div);
scrollToBottom();
};
function addAiMessage(content) {
const div = document.createElement('div');
div.className = 'message ai-message';
div.innerHTML = `<div class="ai-content">${marked.parse(content)}</div>`;
messagesContainer.appendChild(div);
if (typeof hljs !== 'undefined') hljs.highlightAll();
scrollToBottom();
}
function showTypingIndicator() {
if(AppState.isTyping) return;
AppState.isTyping = true;
const i = document.createElement('div');
i.id = 'typingIndicator';
i.className = 'message ai-message';
i.innerHTML = `<div style="background: var(--surface); padding: 10px 16px; border-radius: var(--radius-lg);"><div style="display:flex; gap:4px;"><div style="animation: typingPulse 1.4s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.16s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div><div style="animation: typingPulse 1.4s -0.32s infinite ease-in-out; background-color: var(--text-muted); width: 8px; height: 8px; border-radius: 50%;"></div></div></div><style>@keyframes typingPulse { 0%, 80%, 100% { transform: scale(0.8); opacity: 0.5; } 40% { transform: scale(1.2); opacity: 1; } }</style>`;
messagesContainer.appendChild(i);
scrollToBottom();
}
const hideTypingIndicator = () => {
AppState.isTyping = false;
const i = getEl('typingIndicator');
if (i) i.remove();
};
const escapeHtml = text => { const d = document.createElement('div'); d.textContent = String(text); return d.innerHTML; };
const scrollToBottom = () => messagesContainer.scrollTo({ top: messagesContainer.scrollHeight, behavior: 'smooth' });
function setupEventListeners() {
messageInput.addEventListener('input', () => {
const hasText = messageInput.value.trim().length > 0;
sendBtn.disabled = !hasText;
messageInput.style.height = 'auto';
messageInput.style.height = `${Math.min(messageInput.scrollHeight, 200)}px`;
});
messageInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendMessage(); } });
