case 'Quantum Drug Affinity': interfaceHTML = getDrugAffinityInterface(); break;
case 'Protein-Protein Interaction': interfaceHTML = getPPIInterface(); break;
case 'AlphaGenome': interfaceHTML = getAlphaGenomeInterface(); break;
case 'AlphaFold Proteome': interfaceHTML = getProteomeInterface(); break;
case 'Quantum Docking': interfaceHTML = getQuantumDockingInterface(); break;
case 'Spectral Validation': interfaceHTML = getSpectralValidationInterface(); break;
case 'Quantum Chemistry': interfaceHTML = getQuantumChemistryInterface(); break;
case 'Molecular Dynamics': interfaceHTML = getMolecularDynamicsInterface(); break;
case '3D Conformer Generation': interfaceHTML = getConformerInterface(); break;
case 'Molecule Design': interfaceHTML = getMoleculeDesignInterface(); break;
case 'Chemical Clustering': interfaceHTML = getChemicalClusteringInterface(); break;
case 'Property Prediction': interfaceHTML = getPropertyPredictionInterface(); break;
