async function showProgressAndRun(title, steps, callback) {
const resultsDiv = getEl('service-results');
resultsDiv.innerHTML = `<h3><i class="fas fa-spinner fa-spin accent"></i> ${title}</h3><div id="progress-steps"></div>`;
const progressContainer = getEl('progress-steps');
for (const step of steps) {
const stepDiv = document.createElement('div');
stepDiv.style.cssText = 'padding: 8px; margin: 4px 0; background: var(--glass); border-radius: var(--radius-sm);';
stepDiv.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${step.text}`;
progressContainer.appendChild(stepDiv);
await new Promise(res => setTimeout(res, step.duration));
stepDiv.innerHTML = `<i class="fas fa-check" style="color: var(--secondary);"></i> ${step.text}`;
}
await callback();
}
async function runAlphaFoldPrediction() {
const sequence = getEl('proteinSequence').value.trim();
if (!sequence) { alert('Adjon meg egy protein szekvenciát!'); return; }
const quantum_enhancement = getEl('quantum-enhancement').checked;
const num_recycles = parseInt(getEl('recycle-iterations').value);
const num_diffusion_steps = parseInt(getEl('diffusion-steps').value);
const use_cuda = getEl('cuda-acceleration').checked;
let steps = [
{ text: "Szekvencia validálása...", duration: 500 },
{ text: "MSA generálása...", duration: 1500 },
{ text: "Evoformer futtatása...", duration: 3000 },
{ text: "Szerkezeti modul...", duration: 1000 },
{ text: "Diffúziós modell...", duration: 2500 },
{ text: "Konfidencia számítása...", duration: 800 }
];
if(quantum_enhancement) {
steps.splice(1, 0,
{ text: "Kvantum backend inicializálása...", duration: 1200 },
{ text: "Kvantum áramkör futtatása...", duration: 2000 }
);
}
await showProgressAndRun('AlphaFold 3++ Predikció', steps, async () => {
try {
const data = await apiCall('/alphafold', {
method: 'POST',
body: JSON.stringify({
sequence,
quantum_enhancement,
num_recycles,
num_diffusion_steps,
use_cuda
})
});
let qInfo = '';
if (data.quantum_data) {
qInfo = `
<h4>Kvantum Finomítás</h4>
<div class="stats-grid">
<div class="stat-item"><span class="stat-number">${data.quantum_data.coherence_factor.toFixed(3)}</span><span class="stat-label">Koherencia</span></div>
<div class="stat-item"><span class="stat-number">${data.quantum_data.entanglement_map_max.toFixed(3)}</span><span class="stat-label">Összefonódás</span></div>
<div class="stat-item"><span class="stat-number" style="font-size: 0.9rem; word-break: break-all;">${data.quantum_data.job_id}</span><span class="stat-label">Job ID</span></div>
</div>
`;
}
const resultsHTML = `
<h3><i class="fas fa-check-circle accent"></i> Eredmények</h3>
<div class="result-card">
<h4>Metrikák</h4>
<div class="stats-grid">
<div class="stat-item"><span class="stat-number">${data.plddt.toFixed(1)}</span><span class="stat-label">pLDDT</span></div>
<div class="stat-item"><span class="stat-number">${data.ptm.toFixed(3)}</span><span class="stat-label">pTM</span></div>
<div class="stat-item"><span class="stat-number">${data.iptm.toFixed(3)}</span><span class="stat-label">ipTM</span></div>
<div class="stat-item"><span class="stat-number">${data.ranking_score.toFixed(3)}</span><span class="stat-label">Rangsor</span></div>
</div>
${qInfo}
<div class="action-buttons" style="margin-top: 20px;">
<button class="primary-btn" onclick="downloadFile('predicted.pdb', \`${data.pdb_content}\`)"><i class="fas fa-download"></i> PDB Letöltése</button>
</div>
</div>
`;
getEl('service-results').innerHTML = resultsHTML;
} catch (error) {
getEl('service-results').innerHTML = `<div class="result-card"><h3 style="color: #ff4444;"><i class="fas fa-exclamation-triangle"></i> Hiba</h3><p>${error.message}</p></div>`;
}
});
}
